\[ \text{Value} \to \text{Neuron} \to \text{Layer} \to \text{MLP} \] <ul> <li> <p>Defining a class <code>Value</code>.</p> <pre><code>import math

class Value:

    def __init__(self, data, parents=(), op="", label = ""):
        self.data: float = data
        self.grad: float = 0
        self.op: str = op
        self.backprop = lambda: None
        self.parents: set = set(parents)
        self.label: str = label

    def __repr__(self):
        return f"Value(data={self.data})"

    def __add__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        out = Value(self.data + other.data, (self, other), "+")

        def backprop():
            self.grad += out.grad * 1.0
            other.grad += out.grad * 1.0

        out.backprop = backprop
        return out

    def __mul__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        out =  Value(self.data * other.data, (self, other), "*")

        def backprop():
            self.grad += out.grad * other.data
            other.grad += out.grad * self.data

        out.backprop = backprop
        return out

    def __radd__(self, other):
        return self + other

    def __rmul__(self, other):
        return self * other

    def __pow__(self, other):
        assert isinstance(other, (int, float)), "int/float powers for now"
        out = Value(self.data**other, (self,), f"**{other}")

        def backprop():
            self.grad += out.grad * other * self.data**(other - 1)

        out.backprop = backprop
        return out

    def __truediv__(self, other):
        return self * other**-1

    def __neg__(self):
        return self * -1

    def __sub__(self, other):
        return self + (-other)

    def exp(self):
        x = self.data
        e = math.exp(x)
        out = Value(e, (self,), "exp")

        def backprop():
            self.grad += out.grad * e

        out.backprop = backprop
        return out

    def tanh(self):
        n = self.data
        t = (math.exp(2*n) - 1)/(math.exp(2*n) + 1)
        out = Value(t, (self,), "tanh")

        def backprop():
            self.grad += out.grad * (1 - t**2)

        out.backprop = backprop
        return out

    def relu(self):
        out = Value(0 if self.data &lt; 0 else self.data, (self,), 'relu')

        def backprop():
            self.grad += (out.data &gt; 0) * out.grad

        out.backprop = backprop
        return out

    def backward(self):
        visited = set()
        def dfs(u):
            u.backprop()
            visited.add(u)
            for v in u.parents:
                if v not in visited:
                    dfs(v)
        self.grad = 1.0
        dfs(self)
</code></pre> </li> <li> <p>Defining a class <code>Neuron</code>.</p> <pre><code>import random

class Neuron:

    def __init__(self, num_inputs):
        self.w = [Value(random.uniform(-1, 1)) for _ in range(num_inputs)]
        self.b = Value(random.uniform(-1, 1))

    def __call__(self, x):
        act = sum((wi * xi for wi, xi in zip(self.w, x)), self.b)
        out = act.tanh()
        return out

    def parameters(self):
        return self.w + [self.b]
</code></pre> </li> <li> <p>Defining a class <code>Layer</code>.</p> <pre><code>class Layer:

    def __init__(self, num_inputs, num_outputs):
        self.neurons = [Neuron(num_inputs) for _ in range(num_outputs)]

    def __call__(self, x):
        outs = [n(x) for n in self.neurons]
        return outs[0] if len(outs) == 1 else outs

    def parameters(self):
        return [p for neuron in self.neurons for p in neuron.parameters()]
</code></pre> </li> <li> <p>Defining a class <code>MLP</code>.</p> <pre><code>class MLP:

    def __init__(self, num_inputs, list_outputs):
        size = [num_inputs] + list_outputs
        self.layers = [Layer(
            size[i],
            size[i + 1]
        ) for i in range(len(list_outputs))]

    def __call__(self, x):
        for layer in self.layers:
            x = layer(x)
        return x

    def parameters(self):
        return [p for layer in self.layers for p in layer.parameters()]
